questionvariables.text:
/* Reduction formulae: ratio (sin, cos, tan) x form (180-theta, 180+theta, 360-theta) x theta (30, 45, 60)
   = 27 distinct variants. Every answer is non-zero, so a sign error is always detectable. */
fr : rand([1, 2, 3]);          /* 1 = sin, 2 = cos, 3 = tan */
fm : rand([1, 2, 3]);          /* 1 = 180 - theta (Q II), 2 = 180 + theta (Q III), 3 = 360 - theta (Q IV) */
theta : rand([30, 45, 60]);
ang : if fm = 1 then 180 - theta else if fm = 2 then 180 + theta else 360 - theta;
quad : fm + 1;
/* exact value of the ratio for the acute angle theta */
sv : if theta = 30 then 1/2 else if theta = 45 then sqrt(2)/2 else sqrt(3)/2;
cv : if theta = 30 then sqrt(3)/2 else if theta = 45 then sqrt(2)/2 else 1/2;
tv : if theta = 30 then sqrt(3)/3 else if theta = 45 then 1 else sqrt(3);
bval : if fr = 1 then sv else if fr = 2 then cv else tv;
/* sign of the ratio in the quadrant of ang (CAST) */
sg : if fr = 1 then (if fm = 1 then 1 else -1)
     else if fr = 2 then (if fm = 3 then 1 else -1)
     else (if fm = 2 then 1 else -1);
ta1 : sg*bval;
/* common slip: value of the other ratio (sin and cos swapped, or tan inverted) with the right sign */
cofv : if fr = 1 then cv else if fr = 2 then sv else 1/tv;
tcof : sg*cofv;
